/**
 * UpdateBranchRepoOption options when updating a branch in a repository
 */
export type UpdateBranchRepoOption = Record<string, unknown> & {
  /**
   * New branch name
   */
  "name": string;
};

/**
 * UpdateFileOptions options for updating files
 * Note: `author` and `committer` are optional (if only one is given, it will be used for the other, otherwise the authenticated user will be used)
 */
export type UpdateFileOptions = Record<string, unknown> & {
  "author"?: Identity;
  /**
   * branch (optional) to base this file from. if not given, the default branch is used
   */
  "branch"?: string;
  "committer"?: Identity;
  /**
   * content must be base64 encoded
   */
  "content": string;
  "dates"?: CommitDateOptions;
  /**
   * (optional) will do a force-push if the new branch already exists
   */
  "force_overwrite_new_branch"?: boolean;
  /**
   * from_path (optional) is the path of the original file which will be moved/renamed to the path in the URL
   */
  "from_path"?: string;
  /**
   * message (optional) for the commit of this file. if not supplied, a default message will be used
   */
  "message"?: string;
  /**
   * new_branch (optional) will make a new branch from `branch` before creating the file
   */
  "new_branch"?: string;
  /**
   * sha is the SHA for the file that already exists
   */
  "sha": string;
  /**
   * Add a Signed-off-by trailer by the committer at the end of the commit log message.
   */
  "signoff"?: boolean;
};

/**
 * UpdateRepoAvatarUserOption options when updating the repo avatar
 */
export type UpdateRepoAvatarOption = Record<string, unknown> & {
  /**
   * image must be base64 encoded
   */
  "image"?: string;
};

/**
 * UpdateUserAvatarUserOption options when updating the user avatar
 */
export type UpdateUserAvatarOption = Record<string, unknown> & {
  /**
   * image must be base64 encoded
   */
  "image"?: string;
};

/**
 * UpdateVariableOption defines the properties of the variable to update.
 */
export type UpdateVariableOption = Record<string, unknown> & {
  /**
   * New name for the variable. If the field is empty, the variable name won't be updated. Forgejo will convert it to
   * uppercase.
   */
  "name"?: string;
  /**
   * Value of the variable to update. Special characters will be retained. Line endings will be normalized to LF to
   * match the behaviour of browsers. Encode the data with Base64 if line endings should be retained.
   */
  "value": string;
};

