export type RepoSearchInput = {
  query?: {
    /**
     * show only archived, non-archived or all repositories (defaults to all)
     */
    "archived"?: boolean;
    /**
     * if `uid` is given, search only for repos that the user owns
     */
    "exclusive"?: boolean;
    /**
     * include search of keyword within repository description
     */
    "includeDesc"?: boolean;
    /**
     * show only public, private or all repositories (defaults to all)
     */
    "is_private"?: boolean;
    /**
     * page size of results
     */
    "limit"?: RestInt64;
    /**
     * type of repository to search for. Supported values are "fork", "source", "mirror" and "collaborative"
     */
    "mode"?: string;
    /**
     * sort order, either "asc" (ascending) or "desc" (descending). Default is "asc", ignored if "sort" is not specified.
     */
    "order"?: "asc" | "desc";
    /**
     * page number of results to return (1-based)
     */
    "page"?: RestInt64;
    /**
     * repo owner to prioritize in the results
     */
    "priority_owner_id"?: RestInt64;
    /**
     * include private repositories this user has access to (defaults to true)
     */
    "private"?: boolean;
    /**
     * keyword
     */
    "q"?: string;
    /**
     * sort repos by attribute. Supported values are "alpha", "created", "updated", "size", "git_size", "lfs_size", "stars", "forks" and "id". Default is "alpha"
     */
    "sort"?:
      | "alpha"
      | "created"
      | "forks"
      | "git_size"
      | "id"
      | "lfs_size"
      | "size"
      | "stars"
      | "updated";
    /**
     * search only for repos that the user with the given id has starred
     */
    "starredBy"?: RestInt64;
    /**
     * search only for repos that belong to the given team id
     */
    "team_id"?: RestInt64;
    /**
     * show only template, non-template or all repositories (defaults to all)
     */
    "template"?: boolean;
    /**
     * Limit search to repositories with keyword as topic
     */
    "topic"?: boolean;
    /**
     * search only for repos that the user with the given id owns or contributes to
     */
    "uid"?: RestInt64;
  };
};

